def compute(vars):
    prior_value = vars["v1"]
    current_value = vars["v2"]

    if prior_value == 0:
        return None

    change = current_value - prior_value
    change_ratio = change / prior_value

    return {
        "value": change_ratio,
        "trace": {
            "prior_value": prior_value,
            "current_value": current_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
